import assert from 'node:assert/strict';
import { lowerBlockScope } from './src/compiler/ir_lowering.mjs';
import { SymbolTable } from './src/compiler/symbol_table.mjs';
import { DiagnosticBag } from './src/compiler/diagnostic_bag.mjs';
import { ByteWriter } from './src/lib/byte_writer.mjs';

const symTab = new SymbolTable();
const diag = new DiagnosticBag();
const buf = new ByteWriter();
const okRes = lowerBlockScope({
  declarations: [
    { name: 'a', kind: 'let', initOffset: 4 },
    { name: 'b', kind: 'const', initOffset: 16 },
  ]
}, symTab, diag, buf);
assert.equal(okRes.isOk, true);
assert.deepEqual(okRes.value, { count: 2, bytesHex: '0000000400000010' });
assert.equal(symTab.frames.length, 1);

const buf2 = new ByteWriter();
const failRes = lowerBlockScope({
  declarations: [
    { name: 'x', kind: 'let', initOffset: 8 },
    { name: 'x', kind: 'let', initOffset: 12 },
  ]
}, symTab, diag, buf2);
assert.equal(failRes.isOk, false);
assert.equal(failRes.errorCode, 'E_DUPLICATE_BINDING');
assert.equal(failRes.value, 'x');
assert.equal(diag.items.length, 1);
assert.deepEqual(diag.items[0], { code: 'E_DUPLICATE_BINDING', message: 'Duplicate: x', offset: 12 });
assert.equal(symTab.frames.length, 1);
console.log('ALL OK');
